-- Seed one reusable website quiz for every current Grade 1-6 curriculum topic.
-- Each quiz has exactly five multiple-choice questions on that topic only.
-- Run after 2026_09_19_teacher_student_learning_hub_insights.sql.

begin;
set local search_path = pg_catalog, public;

do $prerequisites$
begin
    if to_regclass('public.profiles') is null
       or to_regclass('public.quizzes') is null
       or to_regclass('public.quiz_questions') is null
       or to_regclass('public.mathverse_schema_migrations') is null then
        raise exception 'Run every MathVerse migration through 2026_09_19 first';
    end if;
end
$prerequisites$;

do $admin_guard$
declare
    admin_role text;
    admin_email text;
    admin_suspended_at timestamptz;
    admin_deactivated_at timestamptz;
begin
    select role::text, email, suspended_at, deactivated_at
      into admin_role, admin_email, admin_suspended_at, admin_deactivated_at
      from public.profiles
     where id = '7607da46-85b3-4cdc-851d-23fd4eb5223e'::uuid;

    if not found then
        raise exception 'The configured curriculum quiz author profile does not exist';
    end if;
    if admin_role is distinct from 'admin' then
        raise exception 'The configured curriculum quiz author is not an administrator';
    end if;
    if admin_suspended_at is not null or admin_deactivated_at is not null then
        raise exception 'The configured curriculum quiz author is not active';
    end if;
    if encode(digest(lower(btrim(admin_email)), 'sha256'), 'hex')
       is distinct from '3c374b3d3b0505ffc8ef13e4d1accf7b9f857f52c35aa8fda91ae9a0b195545c' then
        raise exception 'The configured curriculum quiz author identity does not match';
    end if;
end
$admin_guard$;

create temporary table curriculum_quiz_seed (
    quiz_id uuid primary key,
    topic_key text not null unique,
    topic text not null,
    grade_level integer not null,
    questions jsonb not null
) on commit drop;

insert into pg_temp.curriculum_quiz_seed (quiz_id, topic_key, topic, grade_level, questions)
select quiz_id::uuid, topic_key, topic, grade_level, questions
from jsonb_to_recordset($curriculum_quiz_seed_json$[{"quiz_id":"2f0af2e1-01ec-5dc8-8c64-ecb2ca8a779a","topic_key":"g1-shapes-2d","topic":"Simple 2-Dimensional Shapes","grade_level":1,"questions":[{"question":"A learner draws a figure with 3 straight sides and 3 corners on paper. What shape is it?","choices":["Square","Circle","Triangle","Rectangle"],"correct_answer":2},{"question":"A learner marks a figure with 4 equal sides and 4 corners. What shape is described?","choices":["Circle","Triangle","Square","Rectangle with unequal sides"],"correct_answer":2},{"question":"A learner needs a 4-sided figure with two long sides and two short sides. Which shape fits?","choices":["Rectangle","Circle","Triangle","Square only"],"correct_answer":0},{"question":"A learner cuts a square from one corner to the opposite corner. Which two shapes are formed?","choices":["Two circles","Three rectangles","Two triangles","A square and a circle"],"correct_answer":2},{"question":"A learner joins two equal squares side by side. What larger simple shape is formed?","choices":["One smaller square","Circle","Rectangle","Triangle"],"correct_answer":2}]},{"quiz_id":"62ff431a-e39a-59b6-8538-f71ba181ea5b","topic_key":"g1-whole-numbers-100","topic":"Whole Numbers up to 100","grade_level":1,"questions":[{"question":"A learner writes the number 30. What number comes immediately after it?","choices":["29","32","31","30"],"correct_answer":2},{"question":"A learner looks at the number 26. What number is 1 less than this label?","choices":["24","26","23","25"],"correct_answer":3},{"question":"A learner compares four numbers: 29, 35, 27, 42. Which is greatest?","choices":["35","29","27","42"],"correct_answer":3},{"question":"A learner must arrange 28, 31, 36 from smallest to largest. Which order is correct?","choices":["28 > 31 > 36","28 < 31 < 36","31 < 28 < 36","36 < 31 < 28"],"correct_answer":1},{"question":"A learner reads the counting pattern 20, 30, 40, ___, 60. Which number is missing?","choices":[