ct_answer":2},{"question":"A learner uses the repeating pattern circle, star, star, circle, star, star, circle, star, ___. What comes next?","choices":["star","none","stop","circle"],"correct_answer":0}]},{"quiz_id":"e0e36f14-e492-5a77-a2d9-bc0351b299c4","topic_key":"g1-halves-quarters","topic":"Halves and Quarters","grade_level":1,"questions":[{"question":"A learner divides one serving into 2 equal parts and uses 1 part. What fraction is used?","choices":["1/2","2/1","2/2","1/4"],"correct_answer":0},{"question":"A learner compares one-half and one-quarter of equal-sized items. Which fraction is greater?","choices":["1/2","Neither fraction","1/4","They are equal"],"correct_answer":0},{"question":"A learner has 8 equal quarter-pieces of servings. How many whole servings do they make?","choices":["2","3","1","0"],"correct_answer":0},{"question":"A learner has 6 half-pieces of servings. How many whole servings do they make?","choices":["1","3","2","4"],"correct_answer":1},{"question":"A learner divides one shape into 2 equal parts and uses 1 part. What fraction is used?","choices":["1/2","2/1","2/2","1/4"],"correct_answer":0}]},{"quiz_id":"e94ad532-8141-5ce8-a3bb-13934f4a33a6","topic_key":"g1-money-value-100","topic":"Philippine Money up to ₱100","grade_level":1,"questions":[{"question":"A learner counts three ₱20 bills. What is their total value?","choices":["₱20","₱40","₱60","₱80"],"correct_answer":2},{"question":"A learner receives one ₱10 and one ₱1. How much money is that altogether?","choices":["₱11","₱10","₱9","₱12"],"correct_answer":0},{"question":"A learner compares a ₱20 denomination with a ₱1 denomination. Which has the greater value?","choices":["₱19","₱20","₱21","₱1"],"correct_answer":1},{"question":"A learner must make exactly ₱15 using only ₱5 denominations. How many are needed?","choices":["3 pieces","2 pieces","1 piece","4 pieces"],"correct_answer":0},{"question":"A learner has two ₱10 denominations and one ₱10 denomination. What is the total value?","