percentages","topic":"Percentages, Fractions, and Decimals","grade_level":6,"questions":[{"question":"A learner needs 10% of 200 safety cones. How many is that?","choices":["18","19","21","20"],"correct_answer":3},{"question":"A learner records the fraction 20/100. What percent is this?","choices":["80%","20%","40%","2.0%"],"correct_answer":1},{"question":"A learner converts 25% to decimal form. Which decimal is correct?","choices":["0.15","0.35","0.25","0.05"],"correct_answer":2},{"question":"A learner converts 40% to a fraction in simplest form. Which fraction is correct?","choices":["3/5","2/5","1/3","1/5"],"correct_answer":1},{"question":"A learner finds that 30 out of 60 safety cones are ready. What percent are ready?","choices":["50%","70%","40%","60%"],"correct_answer":0}]},{"quiz_id":"fb7e6800-2ecf-5abb-86d9-59f72d5f1ed7","topic_key":"g6-exponents-gemdas","topic":"Exponential Form and GEMDAS","grade_level":6,"questions":[{"question":"A learner writes 2^2. What is its value?","choices":["2","4","0","6"],"correct_answer":1},{"question":"A learner rewrites 4^2 in expanded form. Which expression is correct?","choices":["4 x 4","4 x 3","2^4","4 + 4"],"correct_answer":0},{"question":"A learner evaluates 4^3 + 4 x 2. What is the result?","choices":["68","64","72","76"],"correct_answer":2},{"question":"A learner evaluates (3 + 1)^2. What is the result?","choices":["12","8","20","16"],"correct_answer":3},{"question":"A learner evaluates 2^3 ÷ 2. What is the result?","choices":["0","4","2","6"],"correct_answer":1}]},{"quiz_id":"8b9e7eab-1c5d-5923-ad7b-45161d0715d4","topic_key":"g6-volume-capacity-units","topic":"Units of Volume and Capacity","grade_level":6,"questions":[{"question":"A learner records a capacity of 5 L. How many milliliters is that?","choices":["6,000 mL","3,000 mL","4,000 mL","5,000 mL"],"correct_answer":3},{"question":"A learner measures the space inside a storage box. Which unit is appropriate?","choices":["Centimeters only","Cubic centimeters","Square centimeters","Kilograms"],"correct_answer":1},{"question":"A learner uses a container with volume 1,000 cm³. What capacity is equivalent?","choices":["10 liters","1 liter","100 liters","1 milliliter"],"correct_answer":1},{"question":"A learner records 1500 mL. How many liters is that?","choices":["2","0.5","1","1.5"],"correct_answer":3},{"question":"A learner compares 2 L and 1,750 mL. Which capacity is greater?","choices":["They are equal","2 L","1,750 mL","Cannot be compared"],"correct_answer":1}]},{"quiz_id":"ef153d91-2637-5ebb-a802-48c9bbc95913","topic_key":"g6-prism-volume","topic":"Volume of Cubes and Rectangular Prisms","grade_level":6,"questions":[{"question":"A learner checks a cube with edge 6 cm. What is its volume?","choices":["144 cm³","252 cm³","180 cm³","216 cm³"],"correct_answer":3},{"question":"A learner checks a box 5 cm long, 3 cm wide, and 3 cm high. What is its volume?","choices":["54 cm³","45 cm³","27 cm³","36 cm³"],"correct_answer":1},{"question":"A learner knows a box volume is 891 cm³, with length 11 cm and width 9 cm. What is its height?","choices":["7 cm","10 cm","8 cm","9 cm"],"correct_answer":3},{"question":"A learner fills a rectangular space with unit cubes in 5 layers of 4 by 3. How many unit cubes fit?","choices":["60 cubes","48 cubes","36 cubes","72 cubes"],"correct_answer":0},{"question":"A learner checks a box 6 cm long, 3 cm wide, and 2 cm high. What is its volume?","choices":["24 cm³","42 cm³","30 cm³","36 cm³"],"correct_answer":3}]},{"quiz_id":"c83d3587-25fe-57e1-aee5-ca8eb61126a2","topic_key":"g6-composite-measurement","topic":"Perimeter and Area of Composite Figures","grade_level":6,"questions":[{"question":"A learner combines non-overlapping rectangles 13 m x 8 m and 7 m x 2 m. What is the total area?","choices":["118 m²","126 m²","110 m²","102 m²"],"correct_answer":0},{"question":"A learner joins rectangles 8 m x 4 m and 4 m x 4 m along a 4 m side. What is the outside perimeter?","choices":["28 m","34 m","32 m","30 m"],"correct_answer":2},{"question":"A learner combines non-overlapping rectangles 9 m x 7 m and 5 m x 5 m. What is the total area?","choices":["95 m²","81 m²","88 m²","74 m²"],"correct_answer":2},{"question":"A learner joins rectangles 7 m x 8 m and 5 m x 4 m along a 4 m side. What is the outside perimeter?","choices":["40 m","42 m","38 m","36 m"],"correct_answer":0},{"question":"A learner combines non-overlapping rectangles 11 m x 4 m and 6 m x 3 m. What is the total area?","choices":["54 m²","58 m²","66 m²","62 m²"],"correct_answer":3}]},{"quiz_id":"612305be-5b82-51c4-86d0-b9925ce45ea4","topic_key":"g6-circle-parts","topic":"Parts and Circumference of a Circle","grade_level":6,"questions":[{"question":"A learner draws a segment from the center of a circle to its edge. What is this segment called?","choices":["Diameter","Radius","Chord only","Circumference"],"correct_answer":1},{"question":"A learner draws a segment through the center with endpoints on the circle. What is it called?","choices":["Radius","Circumference","Arc","Diameter"],"correct_answer":3},{"question":"A learner measures a circle with radius 7 cm. What is its diameter?","choices":["21 cm","7 cm","14 cm","0 cm"],"correct_answer":2},{"question":"A learner measures a circular boundary with radius 8 m. Using pi = 3.14, what is its circumference?","choices":["53.38","47.1","50.24","43.96"],"correct_answer":2},{"question":"A learner measures a circular boundary with radius 10 m. Using pi = 3.14, what is its circumference?","choices":["62.8","65.94","59.66","56.52"],"correct_answer":0}]},{"quiz_id":"0e2226a3-f0bf-555c-9bef-5b04c834c7c0","topic_key":"g6-circle-area","topic":"Area of a Circle","grade_level":6,"questions":[{"question":"A learner plans a circular area with radius 5 m. Using pi = 3.14, what is its area?","choices":["94.2","47.1","78.5","62.8"],"correct_answer":2},{"question":"A learner plans a circular area with radius 7 m. Using pi = 3.14, what is its area?","choices":["109.9","175.84","153.86","131.88"],"correct_answer":2},{"question":"A learner plans a circular area with radius 3 m. Using pi = 3.14, what is its area?","choices":["37.68","9.42","28.26","18.84"],"correct_answer":2},{"question":"A learner plans a circular area with radius 10 m. Using pi = 3.14, what is its area?","choices":["314","345.4","251.2","282.6"],"correct_answer":0},{"question":"A learner plans a circular area with radius 9 m. Using pi = 3.14, what is its area?","choices":["226.08","197.82","282.6","254.34"],"correct_answer":3}]},{"quiz_id":"3fef5361-8831-53be-af90-b61370f2b0d0","topic_key":"g6-composite-circle-area","topic":"Area of Composite Figures with Circles","grade_level":6,"questions":[{"question":"A learner combines a 24 m by 18 m rectangle and a non-overlapping circle of radius 6 m. What is the total area using pi = 3.14?","choices":["507.36","526.2","545.04","563.88"],"correct_answer":2},{"question":"A learner cuts a circle of radius 6 m from a 24 m by 18 m rectangle. What area remains using pi = 3.14?","choices":["318.96","281.28","300.12","337.8"],"correct_answer":0},{"question":"A learner combines a 16 m by 12 m rectangle and a non-overlapping circle of radius 4 m. What is the total area using pi = 3.14?","choices":["229.68","217.12","242.24","254.8"],"correct_answer":2},{"question":"A learner cuts a circle of radius 7 m from a 28 m by 21 m rectangle. What area remains using pi = 3.14?","choices":["390.18","434.14","456.12","412.16"],"correct_answer":1},{"question":"A learner combines a 12 m by 9 m rectangle and a non-overlapping circle of radius 3 m. What is the total area using pi = 3.14?","choices":["126.84","136.26","117.42","145.68"],"correct_answer":1}]},{"quiz_id":"0fbf4a5e-d544-5aef-88c4-b8f5230f91ec","topic_key":"g6-pie-graphs","topic":"Pie Graphs","grade_level":6,"questions":[{"question":"A learner uses a pie graph where 25% of 40 servings are in one category. How many are in that category?","choices":["8","9","10","11"],"correct_answer":2},{"question":"A learner shows 40% of a pie graph. What central angle represents this sector?","choices":["144 degrees","162 degrees","108 degrees","126 degrees"],"correct_answer":0},{"question":"A learner shows a sector of 270 degrees in a pie graph. What percent of the circle is this?","choices":["65%","85%","25%","75%"],"correct_answer":3},{"question":"A learner uses a pie graph where 25% of 60 store items are in one category. How many are in that category?","choices":["13","16","15","14"],"correct_answer":2},{"question":"A learner uses a pie graph where 25% of 200 safety markers are in one category. How many are in that category?","choices":["48","50","49","51"],"correct_answer":1}]},{"quiz_id":"529c8cdf-1c16-54f0-9ef8-d3a90c6e6dde","topic_key":"g6-gcf-lcm","topic":"GCF and LCM","grade_level":6,"questions":[{"question":"A learner groups 12 safety markers of one type and 18 of another into the largest equal groups. What is the GCF?","choices":["4","7","5","6"],"correct_answer":3},{"question":"A learner has schedules repeating every 18 and 24 minutes. After how many minutes will they match again?","choices":["66 minutes","78 minutes","72 minutes","60 minutes"],"correct_answer":2},{"question":"A learner groups 12 store items of one type and 18 of another into the largest equal groups. What is the GCF?","choices":["6","4","7","5"],"correct_answer":0},{"question":"A learner groups 12 servings of one type and 18 of another into the largest equal groups. What is the GCF?","choices":["6","4","5","7"],"correct_answer":0},{"question":"Two schedules repeat every 15 minutes and every 20 minutes. After how many minutes will they match again?","choices":["30 minutes","45 minutes","60 minutes","80 minutes"],"correct_answer":2}]}]$curriculum_quiz_seed_json$::jsonb)
    as seed(quiz_id text, topic_key text, topic text, grade_level integer, questions jsonb);

do $seed_guard$
begin
    if (select count(*) from pg_temp.curriculum_quiz_seed) <> 109 then
        raise exception 'Curriculum quiz seed must contain exactly 109 quizzes';
    end if;
    if (select count(*) from pg_temp.curriculum_quiz_seed where grade_level = 1) <> 15
       or (select count(*) from pg_temp.curriculum_quiz_seed where grade_level = 2) <> 17
       or (select count(*) from pg_temp.curriculum_quiz_seed where grade_level = 3) <> 22
       or (select count(*) from pg_temp.curriculum_quiz_seed where grade_level = 4) <> 19
       or (select count(*) from pg_temp.curriculum_quiz_seed where grade_level = 5) <> 20
       or (select count(*) from pg_temp.curriculum_quiz_seed where grade_level = 6) <> 16 then
        raise exception 'Curriculum quiz seed grade counts are invalid';
    end if;
    if exists (
        select 1 from pg_temp.curriculum_quiz_seed
         where grade_level not between 1 and 6
            or char_length(btrim(topic)) not between 1 and 150
            or topic ~* '^grade[[:space:]]+[1-6]'
            or jsonb_typeof(questions) is distinct from 'array'
            or jsonb_array_length(questions) <> 5
    ) then
        raise exception 'A curriculum quiz has invalid metadata or question count';
    end if;
    if exists (
        select 1
          from pg_temp.curriculum_quiz_seed seed
          cross join lateral jsonb_array_elements(seed.questions) as item(question)
         where jsonb_typeof(item.question) is distinct from 'object'
            or char_length(btrim(item.question ->> 'question')) = 0
            or jsonb_typeof(item.question -> 'choices') is distinct from 'array'
            or jsonb_array_length(item.question -> 'choices') <> 4
            or coalesce(item.question ->> 'correct_answer', '') !~ '^[0-3]$'
            or (
                select count(distinct btrim(choice))
                  from jsonb_array_elements_text(item.question -> 'choices') as choices(choice)
            ) <> 4
    ) then
        raise exception 'A curriculum quiz question is invalid';
    end if;
    if exists (
        select 1
          from pg_temp.curriculum_quiz_seed seed
          cross join lateral jsonb_array_elements(seed.questions) as item(question)
         where concat_ws(' ', seed.topic, item.question ->> 'question', item.question -> 'choices'::text)
               ~* '(calapan|singko|caltex|capitol|nuciti|minsu|jasmai|chlippings|fermacia|rural bank of pola|goodmorning trading|m lhuillier|7-eleven|mr\. diy|g[1-6]_|\m(npc|quest|reward|route|port|passenger|ferry|ferries)\M)'
    ) then
        raise exception 'Game or Calapan-specific wording remains in the curriculum quiz seed';
    end if;
end
$seed_guard$;

insert into public.quizzes as existing (
    id, teacher_id, topic, grade_level, visibility, source_quiz_id,
    version, verified_at, verified_by, updated_at
)
select seed.quiz_id,
       '7607da46-85b3-4cdc-851d-23fd4eb5223e'::uuid,
       seed.topic,
       seed.grade_level,
       'shared',
       null,
       1,
       timezone('utc', now()),
       '7607da46-85b3-4cdc-851d-23fd4eb5223e'::uuid,
       timezone('utc', now())
  from pg_temp.curriculum_quiz_seed seed
on conflict (id) do update
set teacher_id = excluded.teacher_id,
    topic = excluded.topic,
    grade_level = excluded.grade_level,
    visibility = excluded.visibility,
    source_quiz_id = null,
    version = excluded.version,
    verified_at = coalesce(existing.verified_at, excluded.verified_at),
    verified_by = coalesce(existing.verified_by, excluded.verified_by),
    updated_at = excluded.updated_at
where existing.deleted_at is null;

-- Replace only this seed's active quiz content. A quiz intentionally moved to
-- Trash remains untouched when a deployment is retried.
delete from public.quiz_questions question
using pg_temp.curriculum_quiz_seed seed, public.quizzes quiz
where question.quiz_id = seed.quiz_id
  and quiz.id = seed.quiz_id
  and quiz.deleted_at is null;

insert into public.quiz_questions (
    quiz_id, position, grade, type, question,
    choice1, choice2, choice3, choice4, choice5, choice6, correct_answer
)
select seed.quiz_id,
       question.ordinality::integer,
       seed.grade_level,
       'multiple_choice',
       question.value ->> 'question',
       question.value -> 'choices' ->> 0,
       question.value -> 'choices' ->> 1,
       question.value -> 'choices' ->> 2,
       question.value -> 'choices' ->> 3,
       '',
       '',
       question.value ->> 'correct_answer'
  from pg_temp.curriculum_quiz_seed seed
  join public.quizzes quiz on quiz.id = seed.quiz_id and quiz.deleted_at is null
  cross join lateral jsonb_array_elements(seed.questions) with ordinality as question(value, ordinality)
 order by seed.grade_level, seed.topic_key, question.ordinality;

insert into public.mathverse_schema_migrations (migration_key)
values ('2026_09_20_curriculum_single_topic_quizzes.sql')
on conflict (migration_key) do nothing;

notify pgrst, 'reload schema';
commit;
